-- Board titles as on the site (BOS Lead Dev for Nil, 2026-10-16): a problem board has the
-- name of the site's landing table and Problems menu ("Integer Multiplication", "Fourier
-- Transform", "APSP"); the Other bounds rows already had the site's names. Generated by
-- scripts/sync-boards.ts from the site's chat-knowledge.json at 3ab4b26 (updatedAt
-- 2026-10-16T21:17:46Z), which publishes each problem's name. The order is unchanged.
-- Board order and titles: the site's (scripts/sync-boards.ts).
UPDATE board.board SET position = NULL;
UPDATE board.board b SET position = o.position, title = o.title FROM (VALUES
  ('integer-multiplication', 1, 'Integer Multiplication'),
  ('matrix-multiplication', 2, 'Matrix Multiplication'),
  ('exact-dft', 3, 'Fourier Transform'),
  ('3sum', 4, '3SUM'),
  ('apsp', 5, 'APSP'),
  ('subset-sum', 6, 'Subset Sum'),
  ('other-quasi-riemann', 7, 'Quasi-Riemann hypothesis'),
  ('other-catalan', 8, 'Catalan’s constant'),
  ('other-primitive-roots', 9, 'Primitive-root primes'),
  ('other-matroid-prophet', 10, 'One-sample matroid prophet inequality'),
  ('other-contingency-tables', 11, 'Contingency-table sampling'),
  ('other-average-sensitivity', 12, 'Average sensitivity'),
  ('other-van-der-waerden', 13, 'Van der Waerden numbers'),
  ('other-sidorenko', 14, 'Sidorenko counterexample'),
  ('other-unit-distance-grid', 15, 'Unit-distance final grid'),
  ('other-snaky', 16, 'Snaky'),
  ('other-ordered-matrix-removal', 17, 'Ordered matrix removal'),
  ('other-heilbronn-triangle', 18, 'Heilbronn triangle'),
  ('other-haldane-gap', 19, 'Spin-one Haldane gap')
) AS o(slug, position, title) WHERE b.slug = o.slug;
